static QByteArray pinHash(const QString&p,const QByteArray&s){return QPasswordDigestor::deriveKeyPbkdf2(QCryptographicHash::Sha256,p.toUtf8(),s,210000,32);}
Window::Window(Store&s,MusicTransport*transport):store(s),scheduler(s),audio(s,nullptr,transport){
 Q_INIT_RESOURCE(nasaq_brand);setWindowIcon(QIcon(":/nasaq/nasaq-128.png"));
 setWindowTitle("نسق NASAQ 0.2.1 — إدارة الصوت التجاري");resize(1000,650);
 auto root=new QWidget;auto layout=new QVBoxLayout(root);setCentralWidget(root);
 auto logo=new QLabel;logo->setPixmap(QPixmap(":/nasaq/nasaq-128.png").scaled(56,56,Qt::KeepAspectRatio,Qt::SmoothTransformation));auto brandRow=new QHBoxLayout;layout->addLayout(brandRow);
 auto heading=new QLabel("<h1>نسق NASAQ · إدارة الصوت التجاري</h1><p>Engineering preview · Local schedules use this computer’s time zone</p>");heading->setAlignment(Qt::AlignRight|Qt::AlignVCenter);brandRow->addWidget(heading,1);brandRow->addWidget(logo);
 auto bar=new QHBoxLayout;layout->addLayout(bar);
 auto button=[&](const QString&t,const std::function<void()>&fn){auto b=new QPushButton(t);bar->addWidget(b);connect(b,&QPushButton::clicked,this,[this,fn]{guarded(fn);});};
 button("Music / موسيقى",[this]{auto files=QFileDialog::getOpenFileNames(this,"Choose playlist",{},"Audio (*.mp3 *.wav *.flac *.ogg *.m4a)");if(!files.isEmpty()&&!audio.playMusic(files))throw std::runtime_error("Playlist contains missing files");});
 button("Schedule",[this]{addEvent();});button("Prayer timetable",[this]{importPrayers();});button("Music licence",[this]{license();});
 button("CSV",[this]{auto f=QFileDialog::getSaveFileName(this,"Export logs",{},"CSV (*.csv)");if(!f.isEmpty())store.exportCsv(f);});button("PDF",[this]{pdf();});
 auto second=new QHBoxLayout;layout->addLayout(second);
 auto add=[&](QString t,auto fn){auto b=new QPushButton(t);second->addWidget(b);connect(b,&QPushButton::clicked,this,fn);};
 add("STOP ALL",[this]{try{audio.stop();}catch(const std::exception&e){status->setText(e.what());}});
 auto page=new QPushButton("Hold to page / اضغط للتحدث");second->addWidget(page);page->setEnabled(false);
 add("Arm microphone",[this,page]{guarded([this,page]{if(QMessageBox::question(this,"Microphone","Use headphones or an isolated PA output to prevent feedback. Arm hold-to-talk?")==QMessageBox::Yes)page->setEnabled(true);});});
 connect(page,&QPushButton::pressed,this,[this]{guarded([this]{if(!audio.page(true))throw std::runtime_error("No compatible input/output audio format or device");});});
 connect(page,&QPushButton::released,this,[this]{try{audio.page(false);}catch(const std::exception&e){status->setText(e.what());}});
 add("TTS voice",[this]{guarded([this]{auto voices=audio.voices();QStringList names;for(const auto&v:voices)names<<v.name()+" / "+v.locale().name();bool ok=false;auto chosen=QInputDialog::getItem(this,"Installed voices","Arabic/English require an installed matching voice",names,0,false,&ok);if(ok&&names.contains(chosen))audio.setVoice(voices[names.indexOf(chosen)]);});});
 add("Set PIN",[this]{guarded([this]{bool ok;auto p=QInputDialog::getText(this,"Set operator PIN","6–32 characters (local operator lock only)",QLineEdit::Password,{},&ok);if(!ok)return;if(p.size()<6||p.size()>32)throw std::runtime_error("PIN length must be 6–32");QByteArray salt;for(int i=0;i<4;i++){quint32 n=QRandomGenerator::system()->generate();salt.append(reinterpret_cast<const char*>(&n),4);}store.set("pin_salt",salt.toHex());store.set("pin_hash",pinHash(p,salt).toHex());});});
 add("Lock",[this,page]{if(store.get("pin_hash").isEmpty()){status->setText("Set a PIN first");return;}locked=true;Q_EMIT operatorLockChanged(true);page->setEnabled(false);audio.page(false);status->setText("Operator controls locked. STOP remains available.");});
 add("Updates",[this]{guarded([this]{updates();});});
 add("Validate licence",[this]{guarded([this]{bool ok;auto account=QInputDialog::getText(this,"Keygen","Public account ID",QLineEdit::Normal,store.get("keygen_account"),&ok);if(!ok)return;auto product=QInputDialog::getText(this,"Keygen","Public product ID",QLineEdit::Normal,store.get("keygen_product"),&ok);if(!ok)return;auto key=QInputDialog::getText(this,"Keygen","Licence key (sent to Keygen over HTTPS; not saved)",QLineEdit::Password,{},&ok);if(!ok)return;store.set("keygen_account",account);store.set("keygen_product",product);auto service=new Activation(this);connect(service,&Activation::result,this,[this,service](bool valid,const QString&message){status->setText(message+". Preview playback is not activation-gated.");store.log("activation_validation",valid?"valid":"invalid_or_unavailable");service->deleteLater();});service->validate(account,product,key);});});
 events=new QTableWidget;events->setColumnCount(4);events->setHorizontalHeaderLabels({"Local time","Kind","Status","Payload"});events->setEditTriggers(QAbstractItemView::NoEditTriggers);events->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);layout->addWidget(events);
 status=new QLabel;status->setWordWrap(true);layout->addWidget(status);connect(&audio,&Audio::status,status,&QLabel::setText);
 auto notice=new QLabel("Compliance Lite stores operator records and local playback events. It does not certify licensing or regulatory compliance.");notice->setWordWrap(true);layout->addWidget(notice);
 auto timer=new QTimer(this);connect(timer,&QTimer::timeout,this,[this]{try{scheduler.tick(QDateTime::currentDateTimeUtc(),[this](const Event&e){return audio.dispatch(e);});refresh();}catch(const std::exception&e){status->setText(QString("Storage/scheduler error: ")+e.what());}});timer->start(1000);
 locked=!store.get("pin_hash").isEmpty();refresh();
 auto q=store.query("SELECT issuer,expires FROM licenses WHERE expires<=?",{QDate::currentDate().addDays(30).toString(Qt::ISODate)});QStringList reminders;while(q.next())reminders<<q.value(0).toString()+" — "+q.value(1).toString();
 status->setText(reminders.isEmpty()?"Ready. Recovery preserves schedules; audio does not auto-start after restart.":"Licence renewal due or expired: "+reminders.join("; "));
}
bool Window::unlock(){if(!locked)return true;auto until=QDateTime::fromString(store.get("pin_until"),Qt::ISODate);if(until>QDateTime::currentDateTimeUtc()){QMessageBox::warning(this,"Locked","Wait before trying again.");return false;}bool ok;auto p=QInputDialog::getText(this,"Unlock","Operator PIN",QLineEdit::Password,{},&ok);if(!ok)return false;auto h=pinHash(p,QByteArray::fromHex(store.get("pin_salt").toLatin1())).toHex();if(h!=store.get("pin_hash").toLatin1()){int n=store.get("pin_failures").toInt()+1;store.set("pin_failures",QString::number(n));if(n>=5)store.set("pin_until",QDateTime::currentDateTimeUtc().addSecs(60).toString(Qt::ISODate));return false;}store.set("pin_failures","0");store.set("pin_until","");locked=false;Q_EMIT operatorLockChanged(false);return true;}
void Window::guarded(const std::function<void()>&fn){try{if(unlock())fn();}catch(const std::exception&e){QMessageBox::warning(this,"NASAQ",QString::fromUtf8(e.what()));}}
void Window::refresh(){auto q=store.query("SELECT due,kind,status,payload FROM events ORDER BY due DESC LIMIT 200");events->setRowCount(0);while(q.next()){int r=events->rowCount();events->insertRow(r);events->setItem(r,0,new QTableWidgetItem(QDateTime::fromMSecsSinceEpoch(q.value(0).toLongLong()).toString("yyyy-MM-dd HH:mm:ss")));for(int i=1;i<4;i++)events->setItem(r,i,new QTableWidgetItem(q.value(i).toString()));}}
void Window::addEvent(){QDialog d(this);d.setWindowTitle("Schedule one occurrence");QFormLayout form(&d);QComboBox kind;kind.addItems({"music","announcement","adhan","tts"});QDateTimeEdit due(QDateTime::currentDateTime().addSecs(60));due.setDisplayFormat("yyyy-MM-dd HH:mm:ss");QPlainTextEdit payload;form.addRow("Kind",&kind);form.addRow("Local time",&due);form.addRow("File path(s), one per line; or TTS text",&payload);QPushButton browse("Choose audio");form.addRow(&browse);connect(&browse,&QPushButton::clicked,&d,[&]{payload.setPlainText(QFileDialog::getOpenFileNames(&d,"Audio").join('\n'));});QDialogButtonBox buttons(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);form.addRow(&buttons);connect(&buttons,&QDialogButtonBox::accepted,&d,&QDialog::accept);connect(&buttons,&QDialogButtonBox::rejected,&d,&QDialog::reject);if(d.exec()!=QDialog::Accepted)return;if(due.dateTime()<=QDateTime::currentDateTime()||payload.toPlainText().trimmed().isEmpty())throw std::runtime_error("Choose a future time and payload");store.add({QUuid::createUuid().toString(),kind.currentText(),payload.toPlainText(),due.dateTime().toUTC(),kind.currentText()=="adhan"?60:kind.currentText()=="tts"?40:kind.currentText()=="music"?10:50});refresh();}
void Window::importPrayers(){auto f=QFileDialog::getOpenFileName(this,"Import verified prayer timetable (UTC ISO timestamps)",{},"JSON (*.json)");if(f.isEmpty())return;QFile file(f);if(!file.open(QIODevice::ReadOnly))throw std::runtime_error("Cannot read timetable");QJsonParseError err;auto doc=QJsonDocument::fromJson(file.readAll(),&err);if(err.error!=QJsonParseError::NoError||!doc.isArray())throw std::runtime_error("Expected JSON array");QList<Event> batch;QSet<QString> ids;for(auto item:doc.array()){auto o=item.toObject();auto id=o["id"].toString(),utc=o["utc"].toString(),path=o["audio"].toString();auto time=QDateTime::fromString(utc,Qt::ISODate);if(id.isEmpty()||ids.contains(id)||!utc.endsWith('Z')||!time.isValid()||time<=QDateTime::currentDateTimeUtc()||(!path.isEmpty()&&!QFileInfo(path).isFile()))throw std::runtime_error("Invalid/duplicate prayer ID, future UTC time, or missing adhan file");ids.insert(id);batch.append({"prayer:"+id,path.isEmpty()?"prayer":"adhan",path,time,60});}store.exec("BEGIN IMMEDIATE");try{for(auto&e:batch)store.add(e);store.exec("COMMIT");}catch(...){store.exec("ROLLBACK");throw;}refresh();}
void Window::license(){QDialog d(this);QFormLayout form(&d);QLineEdit issuer,ref;QDateEdit expiry(QDate::currentDate().addYears(1));expiry.setCalendarPopup(true);form.addRow("Issuer",&issuer);form.addRow("Reference",&ref);form.addRow("Expiry",&expiry);QDialogButtonBox b(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);form.addRow(&b);connect(&b,&QDialogButtonBox::accepted,&d,&QDialog::accept);connect(&b,&QDialogButtonBox::rejected,&d,&QDialog::reject);if(d.exec()!=QDialog::Accepted)return;if(issuer.text().trimmed().isEmpty()||ref.text().trimmed().isEmpty())throw std::runtime_error("Issuer and reference are required");auto source=QFileDialog::getOpenFileName(this,"Attach licence document (optional)");QString dest;auto id=QUuid::createUuid().toString(QUuid::WithoutBraces);if(!source.isEmpty()){auto dir=QStandardPaths::writableLocation(QStandardPaths::AppLocalDataLocation)+"/documents";QDir().mkpath(dir);dest=dir+"/"+id+"."+QFileInfo(source).suffix();if(!QFile::copy(source,dest))throw std::runtime_error("Document copy failed");}store.exec("INSERT INTO licenses VALUES(?,?,?,?,?)",{id,issuer.text(),ref.text(),expiry.date().toString(Qt::ISODate),dest});store.log("licence_record",id);status->setText("Licence record saved; renewal reminders appear at startup.");}
void Window::pdf(){auto path=QFileDialog::getSaveFileName(this,"Playback report",{},"PDF (*.pdf)");if(path.isEmpty())return;QString html="<h1>نسق NASAQ — Local playback report</h1><p>Operator records; not regulatory certification. Logs are editable by the local Windows account.</p><table border='1'><tr><th>UTC</th><th>Event</th><th>Detail</th></tr>";auto q=store.query("SELECT utc,kind,detail FROM logs ORDER BY id");while(q.next()){html+="<tr>";for(int i=0;i<3;i++)html+="<td>"+q.value(i).toString().toHtmlEscaped()+"</td>";html+="</tr>";}html+="</table>";QPdfWriter writer(path);writer.setPageSize(QPageSize::A4);QTextDocument doc;doc.setHtml(html);doc.print(&writer);if(!QFileInfo(path).size())throw std::runtime_error("PDF output failed");}
void Window::updates(){bool ok;auto repo=QInputDialog::getText(this,"GitHub Releases","Release repository: owner/repo",QLineEdit::Normal,store.get("release_repo"),&ok);if(!ok)return;if(!QRegularExpression("^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$").match(repo).hasMatch())throw std::runtime_error("Invalid repository");store.set("release_repo",repo);auto manager=new QNetworkAccessManager(this);QNetworkRequest req(QUrl("https://api.github.com/repos/"+repo+"/releases/latest"));req.setRawHeader("Accept","application/vnd.github+json");req.setRawHeader("User-Agent","NASAQ-0.2.1");req.setTransferTimeout(10000);auto reply=manager->get(req);connect(reply,&QNetworkReply::finished,this,[this,reply,manager,repo]{if(reply->error()!=QNetworkReply::NoError){QMessageBox::warning(this,"Updates",reply->errorString());}else{auto o=QJsonDocument::fromJson(reply->readAll()).object();auto tag=o["tag_name"].toString();auto version=QVersionNumber::fromString(tag.startsWith('v')?tag.mid(1):tag);if(version.isNull())QMessageBox::warning(this,"Updates","Release does not contain a semantic version tag");else if(version>QVersionNumber(0,2,1)){if(QMessageBox::question(this,"Update available",tag+" is available. Open the GitHub release page?")==QMessageBox::Yes)QDesktopServices::openUrl(QUrl("https://github.com/"+repo+"/releases/latest"));}else QMessageBox::information(this,"Updates","No newer stable version found.");}reply->deleteLater();manager->deleteLater();});}

void Window::closeEvent(QCloseEvent*event){if(locked){event->ignore();status->setText(QStringLiteral("Unlock operator controls before closing NASAQ."));}else QMainWindow::closeEvent(event);}
